using DesignStore.Application.Production; using DesignStore.Domain.Commerce; using DesignStore.Infrastructure.Persistence; using Microsoft.EntityFrameworkCore;
namespace DesignStore.Infrastructure.Commerce;
public sealed class ProductionService(ApplicationDbContext db) : IProductionService
{ public async Task<IReadOnlyList<ProductionSummary>> GetForCustomerAsync(Guid userId,CancellationToken ct)=>await db.ProductionJobs.AsNoTracking().Where(x=>x.UserId==userId).OrderByDescending(x=>x.CreatedAtUtc).Select(x=>new ProductionSummary(x.Id,x.Number,x.ProductNameSnapshot,x.Status,x.PlannedCompletionUtc)).ToListAsync(ct); public Task<ProductionJob?> GetCustomerJobAsync(Guid userId,Guid id,CancellationToken ct)=>db.ProductionJobs.AsNoTracking().Include(x=>x.StatusHistory).Include(x=>x.Notes.Where(n=>n.CustomerVisible)).Include(x=>x.Attachments.Where(a=>a.Visibility==ProductionAttachmentVisibility.Customer)).SingleOrDefaultAsync(x=>x.Id==id&&x.UserId==userId,ct); public async Task<ProductionJob> ChangeStatusAsync(Guid id,ProductionJobStatus status,string? actor,string? note,CancellationToken ct){var job=await db.ProductionJobs.Include(x=>x.StatusHistory).SingleAsync(x=>x.Id==id,ct);if(!ProductionJobRules.CanTransition(job.Status,status))throw new InvalidOperationException($"Invalid production transition {job.Status} -> {status}.");var from=job.Status;job.Status=status;job.StatusHistory.Add(new ProductionJobStatusHistory{FromStatus=from,ToStatus=status,Actor=actor,Note=note});if(status==ProductionJobStatus.Completed)job.ActualCompletionUtc=DateTime.UtcNow;await db.SaveChangesAsync(ct);return job;} }
